#nullable enable // autogenerated

using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using PVZEngine.Collisions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Detections
{
    public class ForcePadDetector : Detector
    {
        public ForcePadDetector(int mask, float affectHeight, bool mustContainCenter)
        {
            canDetectInvisible = true;
            this.mask = mask;
            factionTarget = FactionTarget.Any;
            this.affectHeight = affectHeight;
            this.mustContainCenter = mustContainCenter;
        }
        protected override Bounds GetDetectionBounds(Entity self)
        {
            var padSize = self.GetScaledSize();
            var sizeX = padSize.x;
            var sizeY = affectHeight;
            var sizeZ = padSize.z;
            var source = self.Position;
            var centerX = source.x;
            var centerY = source.y + sizeY * 0.5f;
            var centerZ = source.z;
            return new Bounds(new Vector3(centerX, centerY, centerZ), new Vector3(sizeX, sizeY, sizeZ));
        }
        protected override bool ValidateCollider(DetectionParams param, IEntityCollider collider)
        {
            if (!collider.IsForMain())
                return false;
            return base.ValidateCollider(param, collider);
        }
        public override bool ValidateTarget(DetectionParams self, Entity target)
        {
            if (!base.ValidateTarget(self, target))
                return false;
            if (target.IgnoreForcePad())
                return false;
            if (mustContainCenter)
            {
                var bounds = self.bounds;
                if (!bounds.Contains(target.GetCenter()))
                {
                    return false;
                }
            }
            return true;
        }
        private float affectHeight;
        private bool mustContainCenter;
    }
}
